{
  "items": [
    {
      "name": "MvPolynomial.coeff_X_mul'",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] [DecidableEq σ] (m : σ →₀ ℕ) (s : σ) (p : MvPolynomial σ R) : (MvPolynomial.X s * p).coeff m = if s ∈ m.support then p.coeff (m - fun₀ | s => 1) else 0",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeff_mul_X'",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] [DecidableEq σ] (m : σ →₀ ℕ) (s : σ) (p : MvPolynomial σ R) : (p * MvPolynomial.X s).coeff m = if s ∈ m.support then p.coeff (m - fun₀ | s => 1) else 0",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeff_monomial_mul'",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (m s : σ →₀ ℕ) (r : R) (p : MvPolynomial σ R) : ((MvPolynomial.monomial s) r * p).coeff m = if s ≤ m then r * p.coeff (m - s) else 0",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeff_mul_monomial'",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (m s : σ →₀ ℕ) (r : R) (p : MvPolynomial σ R) : (p * (MvPolynomial.monomial s) r).coeff m = if s ≤ m then p.coeff (m - s) * r else 0",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeff_sub",
      "type": " {R : Type u} (σ : Type u_1) [CommRing R] (m : σ →₀ ℕ) (p q : MvPolynomial σ R) : (p - q).coeff m = p.coeff m - q.coeff m",
      "module": "Mathlib.Algebra.MvPolynomial.CommRing"
    }
  ]
}
